def first_unique_element(lst):
    first_index = {}
    total_count = {}
    for i, x in enumerate(lst):
        if x not in first_index:
            first_index[x] = i
        total_count[x] = total_count.get(x, 0) + 1
    uniques = [x for x in first_index if total_count[x] == 1]
    if not uniques:
        return None
    return min(uniques, key=lambda x: first_index[x])

