def combine_date_time_to_minutes(year, month, day, time_str):
    cumulative = [0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334]
    leap = (year % 4 == 0 and year % 100 != 0) or year % 400 == 0
    doy = cumulative[month - 1] + day + (1 if (leap and month > 2) else 0)
    h, m = time_str.split(':')
    return (doy - 1) * 1440 + int(h) * 60 + int(m)

def is_valid_sudoku_box(box):
    if len(box) != 9:
        return False
    from collections import Counter
    nonzero = [x for x in box if x != 0]
    if not all(1 <= x <= 9 for x in nonzero):
        return False
    counts = Counter(nonzero)
    return all(c == 1 for c in counts.values())

