def center_moving_average(lst, radius):
    n = len(lst)
    def window_avg(i):
        lo = max(0, i - radius)
        hi = min(n, i + radius + 1)
        chunk = lst[lo:hi]
        return round(sum(chunk) / len(chunk))
    return [window_avg(i) for i in range(n)]

