def mask_phone_intl(phone):
    parts = phone.split('-')
    n = len(parts)
    result = []
    for i, p in enumerate(parts):
        if i == 0 or i == n - 1:
            result.append(p)
        else:
            result.append('*' * len(p))
    return '-'.join(result)

def oxford_join_semicolon(items):
    if not items:
        return ''
    if len(items) == 1:
        return items[0]
    sep = ';' if any(',' in it for it in items) else ','
    pre_and_sep = sep if len(items) >= 3 else ''
    body = (sep + ' ').join(items[:-1]) if len(items) >= 3 else items[0]
    return f'{body}{pre_and_sep} and {items[-1]}'

